BEGIN;
SELECT set_config('app.cure_command_parameters',$cure_capsule${
  "schema_version": "cure-command-parameters/1",
  "source_bundle_sha256": "e14b2a7fd1bbe0d0dad34c12d2176bc1347e6860e205f142d9098f4ae3d559dc",
  "baseline_custody": {
    "ref": "cure_command_root.baseline.json#canonical_preimage/rawUTF8",
    "sha256": "7de36fc81053902e6fbfa99c332ee75544f7a8acdb26ebfd9c6ab108045bcf7f"
  },
  "compatibility": {
    "ref": "cure_command.contratto.md",
    "sha256": "df57a5ed906fcf460bfec0d54c90461f2674a2fdc298037c864f8166b574d0f8",
    "scope": "existing_mission_capabilities_only",
    "new_techniques_staff_pass": false
  },
  "expected_content_admission_rows_sha256": "904e260a2e3b48a6667b0ced2ed380dc45ef3a904f614e06be706897e5ad8b78",
  "review": {
    "ref": "management/candidati/COMBAT-COMPOSITE_2026-09-01/candidato/catalogo_completo/CURE_COMMAND_REVIEW.json#R1",
    "sha256": "5837c096f4ebc384d8f9e296f2f643a5135db939dcc5168bece56db49a8848ec",
    "P0": 0,
    "P1": 0,
    "P2": 0
  }
}$cure_capsule$,true);
DO $cure_command_preflight$
DECLARE pin constant text:='99aa6ecfb6bb8b7d3ed7dd544b543a72ad295733e526c3efa76b8595acf70179';p jsonb;r mission_factory_owner.editor_release_readiness%ROWTYPE;n integer;
BEGIN
 IF current_user<>'postgres'OR session_user<>'postgres'OR auth.uid()IS NOT NULL THEN RAISE EXCEPTION 'cure_command_operator';END IF;
 PERFORM set_config('search_path','',true);p:=nullif(current_setting('app.cure_command_parameters',true),'')::jsonb;
 IF pin!~'^[0-9a-f]{64}$'OR p IS NULL OR public.combat_v2_sha256(p)<>pin OR p->>'schema_version'IS DISTINCT FROM 'cure-command-parameters/1'
 THEN RAISE EXCEPTION 'cure_command_parameters_required';END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('C1266:GENERIC-AI:AVAILABILITY',0))THEN RAISE EXCEPTION 'cure_command_busy';END IF;
 SELECT * INTO STRICT r FROM mission_factory_owner.editor_release_readiness WHERE singleton FOR UPDATE NOWAIT;
 IF encode(extensions.digest(convert_to(r.canonical_preimage,'UTF8'),'sha256'),'hex')IS DISTINCT FROM r.revision_sha256 THEN RAISE EXCEPTION 'cure_command_raw_root_drift';END IF;
 IF EXISTS(SELECT 1 FROM public.combat_v2_sessions WHERE state='in_corso'AND closed_at IS NULL)
 OR EXISTS(SELECT 1 FROM public.master_v2_sessions WHERE stato NOT IN('chiusa','annullata')AND closed_at IS NULL)
 THEN RAISE EXCEPTION 'cure_command_native_quiescence_required';END IF;
 IF EXISTS(SELECT 1 FROM combat_panel_private.cure_gate_v1 WHERE public_enabled)
 OR EXISTS(SELECT 1 FROM combat_v2_genjutsu_internal.gate WHERE public_enabled)
 THEN RAISE EXCEPTION 'cure_command_public_opening_out_of_scope';END IF;
 IF NOT EXISTS(SELECT 1 FROM combat_panel_private.cure_gate_v1 WHERE singleton AND contract_version='palmo-curativo/1')
 OR NOT EXISTS(SELECT 1 FROM combat_v2_genjutsu_internal.gate WHERE singleton AND version=1)THEN RAISE EXCEPTION 'cure_command_gate_row_required';END IF;
 PERFORM set_config('app.cure_command_cure_gate_before',(SELECT to_jsonb(g)::text FROM combat_panel_private.cure_gate_v1 g WHERE singleton),true);
 PERFORM set_config('app.cure_command_paralisi_gate_before',(SELECT to_jsonb(g)::text FROM combat_v2_genjutsu_internal.gate g WHERE singleton),true);
 IF md5((SELECT prosrc FROM pg_proc WHERE oid='clan_innata_private.eligibility_release_assert()'::regprocedure))<>'250e7511806ab0fe07b6bf24b2a1770a'
 THEN RAISE EXCEPTION 'cure_command_guard_must_remain_unchanged';END IF;
 IF r.revision_sha256<>'7de36fc81053902e6fbfa99c332ee75544f7a8acdb26ebfd9c6ab108045bcf7f'OR r.observed_revision_sha256 IS DISTINCT FROM r.revision_sha256
 OR public.combat_v2_sha256(to_jsonb(r))<>'86056394b0a33c29c75f828d6fccd348ac4d6d9009cb95906d0a3b1b7c5a0e42'OR octet_length(r.canonical_preimage)<>514748
 THEN RAISE EXCEPTION 'cure_command_current_root_drift';END IF;
 IF NOT clan_innata_private.catalogo_eligibility_release_v1()THEN RAISE EXCEPTION 'cure_command_baseline_peer_seal';END IF;
END $cure_command_preflight$;
